cceleration, stillness"}, {"id": "1b6dc800-fb04-4908-ad4c-5a1510491135", "type": "concept", "title": "Private versus public body"}, {"id": "1126f76b-6aaa-4d59-8c6c-9846233ae1ac", "type": "concept", "title": "Energy shifts under pressure"}], "description": "The gist is to make character physically repeatable."}, {"id": "762894c0-00aa-4e51-9caa-7dfa8ea566a9", "type": "subtopic", "title": "Transformation With Care", "children": [{"id": "04a6a8c1-6866-406a-9614-32bd4b7c69d6", "type": "concept", "title": "Avoiding caricature"}, {"id": "faa900e1-0299-486c-80f2-7148910cb676", "type": "concept", "title": "Access and disability awareness"}, {"id": "614f79fa-8731-47e9-bab8-1436766c464d", "type": "concept", "title": "Safe exits from character work"}], "description": "Students develop range while respecting real bodies and identities."}]}, {"id": "cb0fd3e5-4c46-4308-80e1-88b5eb657bb2", "type": "topic", "title": "Integrating Voice and Body", "description": "The actor's voice and body must act together. This culminating topic connects breath, speech, movement, text, partner, and space.", "children": [{"id": "cac25323-c632-4fc0-af24-ea83412e5a52", "type": "subtopic", "title": "Text in the Body", "children": [{"id": "2ccc2b5e-4eb9-4771-aa53-540d7e2485c6", "type": "concept", "title": "Operative words"}, {"id": "8feb050e-b00a-4b63-bf05-edd9a3e42724", "type": "concept", "title": "Breath, gesture, and thought"}, {"id": "d7acec25-e88a-4391-bfdc-b909e4fcc43e", "type": "concept", "title": "Verse and heightened text basics"}], "description": "Students physicalize language without illustrating every word."}, {"id": "3ba4046c-abf4-4455-a6d1-c79a992bec85", "type": "subtopic", "title": "Movement With Speech", "children": [{"id": "f1b66dbb-bd01-4f78-9d57-9594a833b467", "type": "concept", "title": "Projection in motion"}, {"id": "a6a573c6-3831-47f9-973b-4740d74efffa", "type": "concept", "title": "Pace, breath, and blocking"}, {"id": "7cfdeb90-f12d-4050-ae46-8ed330b6eb4e", "type": "concept", "title": "Action-driven movement"}], "description": "Actors practice clarity while moving through space."}, {"id": "51111738-62cc-41de-a0b6-23ae248ff3db", "type": "subtopic", "title": "Partner and Ensemble Integration", "children": [{"id": "af874f6c-3f92-4ad7-80b2-ade708e50473", "type": "concept", "title": "Listening through the body"}, {"id": "7b44e950-b0f4-4648-9212-ded23bfd30f8", "type": "concept", "title": "Group rhythm"}, {"id": "983d5c5d-11cc-4b98-a301-812f95c034f1", "type": "concept", "title": "Spatial relationship and cueing"}], "description": "The unit turns individual technique into shared performance."}]}, {"id": "454c390d-87a1-4de5-83ec-af3a195f607a", "type": "topic", "title": "Performance Sustainability and Consent", "description": "Voice/movement training must include safety, consent, and care. Students learn how boundaries support, rather than limit, artistic risk.", "children": [{"id": "34d99dd0-12cf-4400-91a4-bd7eaad3da78", "type": "subtopic", "title": "Consent in Physical Work", "children": [{"id": "079bd395-c02e-4067-a64d-867042916a8d", "type": "concept", "title": "Opt-in and opt-out processes"}, {"id": "54d0c9fc-3c73-480e-ab9a-92899387d25e", "type": "concept", "title": "Partner work agreements"}, {"id": "2db12c01-1514-4225-8c9e-945d404f6992", "type": "concept", "title": "Check-ins and repair"}], "description": "Students practice clear language around touch, proximity, and intensity."}, {"id": "915339c3-1241-43d3-a4da-8a05a89827f7", "type": "subtopic", "title": "Nervous-System Awareness", "children": [{"id": "c5c70b53-ec50-488c-b7db-707c57a7f09d", "type": "concept", "title": "Activation and grounding"}, {"id": "d332e4f2-f9b3-4f96-a604-f82e48f5efbb", "type": "concept", "title": "Return-to-neutral practices"}, {"id": "f31eaa18-69b7-4082-bbd7-8c84bd7335b9", "type": "concept", "title": "Debriefing intense work"}], "description": "The course recognizes performance as embodied stress."}, {"id": "a298b6fd-6b69-411b-8188-de9d873af152", "type": "subtopic", "title": "Long-Term Training Habits", "children": [{"id": "57dfa5ce-c2c8-4030-a4ba-e9e5bea36f7a", "type": "concept", "title": "Warm-up, cool-down, rest, and reflection"}, {"id": "0f84f09e-4cdc-447b-af59-7f9e94ed0c3d", "type": "concept", "title": "Cross-training and injury prevention"}, {"id": "2a754828-da9a-4bb0-88e2-219a327b5e88", "type": "concept", "title": "Preparing for Acting II and production work"}], "description": "Students leave with a repeatable practice plan."}]}], "dbBacked": true}$vomvjson$::jsonb,
