set
  title = 'Voice and Movement',
  goal = 'Voice and Movement',
  summary = 'Voice and Movement introduces actors to the disciplined training of breath, sound, speech, alignment, release, movement vocabulary, gesture, and embodied character work. Students learn to make vocal and physical choices that are expressive, repeatable, healthy, and connected to text, partner, space, and ensemble. The course prepares students for Acting II, period/style work, production practicum, auditions, and rehearsal rooms where vocal clarity, physical presence, and collaborative responsibility are expected.',
  data = $vomvjson${"slug": "voice-and-movement", "title": "Voice and Movement", "description": "Voice and Movement introduces actors to the disciplined training of breath, sound, speech, alignment, release, movement vocabulary, gesture, and embodied character work. Students learn to make vocal and physical choices that are expressive, repeatable, healthy, and connected to text, partner, space, and ensemble. The course prepares students for Acting II, period/style work, production practicum, auditions, and rehearsal rooms where vocal clarity, physical presence, and collaborative responsibility are expected.", "topics": [{"id": "ebd2892a-a5a8-47e1-8fa8-cf838b592430", "type": "topic", "title": "Breath Support", "description": "Breath is the actor's base of sound, impulse, rhythm, and presence. This unit develops reliable support without stiffness or strain.", "children": [{"id": "4561f816-e99d-4948-8194-c0263db0f25c", "type": "subtopic", "title": "Breath Awareness", "children": [{"id": "07b31bba-f56f-44f4-a381-9e15ae984fed", "type": "concept", "title": "Body scan and breath mapping"}, {"id": "6b5ec31c-f529-4b86-8e51-afaa0c6b3d29", "type": "concept", "title": "Rib, diaphragm, back, and pelvic-floor awareness"}, {"id": "5ab3315b-628a-4a7f-96c6-56d841acce7f", "type": "concept", "title": "Recognizing breath habits under attention"}], "description": "Students learn where breath is free, held, shallow, or forced."}, {"id": "84d521f0-ea89-4715-a5e7-21cf869f437c", "type": "subtopic", "title": "Breath and Thought", "children": [{"id": "7dad8d84-b5fc-41d4-8409-660d134b3649", "type": "concept", "title": "Breath before speech"}, {"id": "8574f01b-6732-4829-8ff4-79555d6b05ab", "type": "concept", "title": "Thought units and phrase length"}, {"id": "b7714d2f-e9c0-4141-b1fd-aa0ea31ac7d6", "type": "concept", "title": "Breath as preparation for action"}], "description": "The point is to connect breath to intention and phrase, not mechanical inhaling."}, {"id": "fa3906a5-9a4f-46ae-ae23-6361a623a06d", "type": "subtopic", "title": "Support Without Strain", "children": [{"id": "85b34b2e-ad24-4cf2-9510-f91f6c1c7e4e", "type": "concept", "title": "Released onset"}, {"id": "13276150-2e53-4aec-ab25-f0809dfbdc6f", "type": "concept", "title": "Sustained sound"}, {"id": "250c42d9-6c24-472d-b342-e5c4aa8c8a3c", "type": "concept", "title": "Projection versus pushing"}], "description": "Students practice usable volume and stamina while protecting the voice."}]}, {"id": "42578007-2438-400e-b4b6-b6a684872824", "type": "topic", "title": "Vocal Production and Resonance", "description": "Students explore how sound travels through the body and space. Resonance work expands range, color, and expressive possibility.", "children": [{"id": "279c0667-cc38-4efd-997d-b60e9a4823e9", "type": "subtopic", "title": "Sound Source and Onset", "children": [{"id": "48eee72d-722b-4385-8472-3f8ea752cb86", "type": "concept", "title": "Gentle onset"}, {"id": "aa1d4b06-82d3-4de8-97d1-f2e6884d7a37", "type": "concept", "title": "Vocal fold awareness"}, {"id": "96079d03-86c9-4c1b-a626-12bffe48c034", "type": "concept", "title": "Hum, sigh, and open sound"}], "description": "Actors learn how tone begins and how to avoid harsh or breathy habits."}, {"id": "197a102c-fccf-4b18-9a5d-a954ac4d58e4", "type": "subtopic", "title": "Resonating Spaces", "children": [{"id": "1205a92e-33fa-4c28-be52-578396ce6de3", "type": "concept", "title": "Chest, mouth, nasal, mask, and head resonance"}, {"id": "a6d1e813-8692-4254-a515-56975f472233", "type": "concept", "title": "Vocal color and emotional tone"}, {"id": "baed8613-f045-497b-ac31-61b3cc82a762", "type": "concept", "title": "Resonance shifts for character and space"}], "description": "The gist is to discover vibration as a physical experience."}, {"id": "fa8194f3-fc20-4991-be97-5eb80139b2cb", "type": "subtopic", "title": "Range and Flexibility", "children": [{"id": "0473e239-ac6c-4b6d-b0ce-18648ae712df", "type": "concept", "title": "Pitch, volume, tempo, and rhythm"}, {"id": "97a25635-f16e-4259-8b8b-96c9cad87f4a", "type": "concept", "title": "Vocal variety in text"}, {"id": "b4defb09-9960-4a88-8065-de9c66105ab1", "type": "concept", "title": "Stamina and recovery"}], "description": "Students build expressive range without forcing it."}]}, {"id": "73955a5a-af07-43f2-a3c2-9d1448868c90", "type": "topic", "title": "Articulation and Diction", "description": "Clear speech lets complex thought reach the audience. This section treats diction as muscular, imaginative, and character-driven.", "children": [{"id": "76ae246e-8c49-451c-8845-0289929ddc09", "type": "subtopic", "title": "Consonant Energy", "children": [{"id": "99787b02-2f3a-4843-a74c-0ecd198543f9", "type": "concept", "title": "Plosives, fricatives, nasals, liquids, and glides"}, {"id": "758a4c63-4825-4867-97fb-201ead643685", "type": "concept", "title": "Final consonants"}, {"id": "441dff75-6fb2-4172-8625-6eeabb18f4c0", "type": "concept", "title": "Speed with clarity"}], "description": "Students strengthen precision without becoming artificial."}, {"id": "807f13b4-b8c6-4d2f-ba14-f97ae8e88792", "type": "subtopic", "title": "Vowel Shape and Text", "children": [{"id": "3a1d80db-dfc7-45ea-9aed-554769103c8b", "type": "concept", "title": "Open and closed vowels"}, {"id": "d555c6ad-d5d6-472b-a409-88e69d39571f", "type": "concept", "title": "Length, stress, and musicality"}, {"id": "43d51316-9e62-49a6-b6ea-d4c990a2e7df", "type": "concept", "title": "Vowels in heightened language"}], "description": "Vowels carry tone, feeling, and line."}, {"id": "d5ae6d14-3523-4894-ae89-b609f7ba753c", "type": "subtopic", "title": "Dialect and Standard Speech Awareness", "children": [{"id": "14c468b6-669f-4b60-a08f-0b295826436e", "type": "concept", "title": "Home voice and performance voice"}, {"id": "0d7d0598-a55e-4f28-930d-29846ab5c5ba", "type": "concept", "title": "IPA basics and listening"}, {"id": "63be59a0-4915-4368-8f42-81be6523b509", "type": "concept", "title": "Accent work without caricature"}], "description": "Students approach speech variation ethically and descriptively."}]}, {"id": "410404db-0ab5-4bcc-895c-73333ac62dd5", "type": "topic", "title": "Vocal Health", "description": "Actors need sustainable habits for rehearsal, performance, auditions, and recovery. This topic makes care part of craft.", "children": [{"id": "7e18a712-b457-43a5-807b-465bd16be614", "type": "subtopic", "title": "Daily Care", "children": [{"id": "b2adb536-d03c-4bc5-9904-9948281d00e0", "type": "concept", "title": "Hydration, sleep, warm-up, and cool-down"}, {"id": "37945ded-5c4b-4071-a78d-dabe4aa095e7", "type": "concept", "title": "Environmental irritants"}, {"id": "7a68653d-50c1-4fd7-9eea-a3e0bf18413c", "type": "concept", "title": "Recognizing fatigue"}], "description": "Students learn routines that maintain vocal readiness."}, {"id": "b891d417-4240-4760-95e2-6f3667ba650c", "type": "subtopic", "title": "Load Management", "children": [{"id": "bdc50954-bbe3-4666-a58c-c65f05c3906f", "type": "concept", "title": "Long rehearsal days"}, {"id": "eb000fa3-0e49-43c8-8201-ecb6e89c6f13", "type": "concept", "title": "Shouting, whispering, and emotional scenes"}, {"id": "c9a4ad5b-927c-4a62-a316-088bd38d2625", "type": "concept", "title": "Amplification and room size"}], "description": "The unit connects vocal demand to rehearsal planning."}, {"id": "803d1933-c787-45a3-8668-d6153bf4f603", "type": "subtopic", "title": "When to Seek Help", "children": [{"id": "90a19851-9c43-4337-a20f-7da5a384be51", "type": "concept", "title": "Persistent hoarseness"}, {"id": "4cb897b5-9e94-4021-b1cd-2c8972bc36ec", "type": "concept", "title": "Pain, loss of range, and strain"}, {"id": "db31df65-c767-42d4-8840-c2287407629d", "type": "concept", "title": "Voice professionals and medical referral"}], "description": "Students learn limits of classroom technique."}]}, {"id": "355c0787-307f-42f7-87f6-180628bd18e7", "type": "topic", "title": "Body Awareness and Alignment", "description": "Alignment is dynamic organization, not a fixed pose. Students learn efficient body use that supports breath, voice, and action.", "children": [{"id": "92a586cb-5fbf-4461-8011-9e9006044811", "type": "subtopic", "title": "Body Mapping", "children": [{"id": "18fdc00d-bfc4-4a13-9f17-cc5eee22d324", "type": "concept", "title": "Spine, pelvis, feet, head-neck relationship"}, {"id": "bbd9dfd7-f32e-4756-aeed-9fe049940245", "type": "concept", "title": "Joint freedom and skeletal support"}, {"id": "67bcd57b-35bd-4acf-9b19-d17c67aaadd5", "type": "concept", "title": "Habit versus choice"}], "description": "Students develop anatomical awareness for performance."}, {"id": "3b662824-095d-42ab-980f-608d8a239dae", "type": "subtopic", "title": "Balance and Grounding", "children": [{"id": "aac5d7d5-2037-4391-852b-fc85927150f0", "type": "concept", "title": "Weight distribution"}, {"id": "b42f2d50-d591-4b82-971e-62ca9105b3cc", "type": "concept", "title": "Center, gravity, and floor contact"}, {"id": "7bf7566b-db3a-460a-b622-adc6d0a57254", "type": "concept", "title": "Readiness to move"}], "description": "The point is to feel available, stable, and mobile."}, {"id": "5787eb8e-c46d-4156-977f-797e55b00144", "type": "subtopic", "title": "Alignment in Action", "children": [{"id": "ca06b3aa-829b-4c88-aef6-adb50cdd2904", "type": "concept", "title": "Walking, turning, sitting, rising"}, {"id": "c68fde8e-8457-4f11-bf6b-3e5f214204a8", "type": "concept", "title": "Speaking while moving"}, {"id": "328fc1ec-c40b-4632-9bbf-d2b1388ce239", "type": "concept", "title": "Alignment under emotional stakes"}], "description": "Students carry alignment into rehearsal behavior."}]}, {"id": "62788324-ae24-41f6-bbb3-9be157e63973", "type": "topic", "title": "Physical Relaxation and Release", "description": "Release work removes unnecessary effort so actors can respond with precision. Relaxation here means active availability.", "children": [{"id": "abf0102f-53d9-47bc-97e7-df3eb79616b2", "type": "subtopic", "title": "Tension Patterns", "chil